mapper.select:
SELECT * FROM products

    game_id = #{gameId}
    AND status = #{status}

ORDER BY created_at DESC

mapper.update:
UPDATE products
SET game_id = #{gameId}, sku = #{sku}, name = #{name}, amount_minor = #{amountMinor}, currency = #{currency},
    platform = #{platform}, server_region = #{serverRegion}, delivery_type = #{deliveryType},
    status = #{status}, updated_at = #{updatedAt}
